#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

/* LD_PRELOAD hook for CycloneDDS dds_write: dump + in-place rewrite of a
   marker string inside the serialized sample.
   Phase 1: MARKER=AAAA... dump layout, find the name field.
   Phase 2: replace MARKER with REPLACEMENT (same length). */

typedef int (*dds_write_fn)(int wr, const void *data);
static dds_write_fn real_write = NULL;

static const char *MARKER;
static const char *REPLACEMENT;

static void dump_sample(const void *data, int len) {
    FILE *f = fopen("/tmp/dds_dump.txt", "a");
    if (!f) return;
    const unsigned char *p = (const unsigned char *)data;
    fprintf(f, "== dds_write data=%p ==\n", data);
    for (int i = 0; i < len; i += 16) {
        fprintf(f, "%04x: ", i);
        for (int j = 0; j < 16 && i + j < len; j++) fprintf(f, "%02x ", p[i + j]);
        fprintf(f, " |");
        for (int j = 0; j < 16 && i + j < len; j++)
            fprintf(f, "%c", (p[i + j] >= 32 && p[i + j] < 127) ? p[i + j] : '.');
        fprintf(f, "|\n");
    }
    fclose(f);
}

int dds_write(int wr, const void *data) {
    if (!real_write) real_write = (dds_write_fn)dlsym(RTLD_NEXT, "dds_write");
    if (!MARKER) {
        MARKER = getenv("HOOK_MARKER");          /* e.g. 25 x 'A' */
        REPLACEMENT = getenv("HOOK_REPLACE");    /* same length or NULL */
    }
    if (data) {
        unsigned char *p = (unsigned char *)data;
        /* scan a generous window; strings may be inline or behind a ptr.
           Try inline scan of first 4KB. */
        int found = 0;
        if (MARKER) {
            size_t ml = strlen(MARKER);
            for (int i = 0; i < 4096 - (int)ml; i++) {
                if (memcmp(p + i, MARKER, ml) == 0) {
                    FILE *f = fopen("/tmp/dds_dump.txt", "a");
                    if (f) { fprintf(f, "MARKER at offset %d\n", i); fclose(f); }
                    if (REPLACEMENT && strlen(REPLACEMENT) == ml)
                        memcpy(p + i, REPLACEMENT, ml);
                    found = 1;
                    break;
                }
            }
        }
        if (!found) dump_sample(data, 512);
    }
    return real_write(wr, data);
}

