#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/fanotify.h>
#include <sys/types.h>
#include <limits.h>

/* fan_watch: log every FAN_OPEN system-wide with pid+path, filtered to
   paths containing a needle (argv[1]) or pid==target (argv[2], optional). */
int main(int argc, char **argv) {
    const char *needle = argc > 1 ? argv[1] : "config_service";
    pid_t target = argc > 2 ? atoi(argv[2]) : 0;
    int fd = fanotify_init(FAN_CLASS_NOTIF | FAN_NONBLOCK | FAN_CLOEXEC,
                           O_RDONLY | O_LARGEFILE | O_CLOEXEC);
    if (fd < 0) { perror("fanotify_init"); return 1; }
    if (fanotify_mark(fd, FAN_MARK_ADD | FAN_MARK_MOUNT, FAN_OPEN, AT_FDCWD, "/") < 0) {
        perror("fanotify_mark"); return 1;
    }
    char buf[8192];
    FILE *out = fopen("/tmp/fan_watch.log", "a");
    if (!out) return 1;
    setvbuf(out, NULL, _IOLBF, 0);
    fprintf(out, "== fan_watch start needle=%s target=%d ==\n", needle, target);
    for (;;) {
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n <= 0) { usleep(50000); continue; }
        struct fanotify_event_metadata *m = (struct fanotify_event_metadata *)buf;
        while (FAN_EVENT_OK(m, n)) {
            if (m->vers == FANOTIFY_METADATA_VERSION && m->fd >= 0) {
                char link[64], path[PATH_MAX];
                snprintf(link, sizeof(link), "/proc/self/fd/%d", m->fd);
                ssize_t l = readlink(link, path, sizeof(path) - 1);
                if (l > 0) {
                    path[l] = 0;
                    if (strstr(path, needle) || (target && m->pid == target))
                        fprintf(out, "pid=%d path=%s\n", m->pid, path);
                }
                close(m->fd);
            }
            m = FAN_EVENT_NEXT(m, n);
        }
    }
    return 0;
}

