#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Manual-cycle btgatt ASLR/brk distribution sampler.
Service must be mscli-stopped first (master hands-off).
Each round: setsid start run.sh -> wait -> sample (base, heap, FILE*) -> kill."""
import os, re, time, struct, subprocess, sys

WF = 0x2e1e0
L20 = WF + 0x818 + 0x20
ROUNDS = int(sys.argv[1]) if len(sys.argv) > 1 else 25
BT = '/unitree/module/network_manager/upper_bluetooth/btgatt-server'

def start():
    subprocess.Popen(['setsid', 'bash', '/unitree/module/network_manager/run.sh'],
                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, stdin=subprocess.DEVNULL)

def find_pid():
    for _ in range(30):
        try:
            out = subprocess.check_output(['pgrep', '-x', 'btgatt-server']).decode().split()
            if out:
                return int(out[0])
        except Exception:
            pass
        time.sleep(0.3)
    return None

def sample(pid):
    maps = open(f'/proc/{pid}/maps').read().splitlines()
    exe = [l for l in maps if 'btgatt-server' in l and 'r-xp' in l]
    if not exe:
        return None
    base = int(exe[0].split('-')[0], 16)
    heap = None
    for l in maps:
        if '[heap]' in l:
            heap = int(l.split('-')[0], 16)
            break
    with open(f'/proc/{pid}/mem', 'rb', buffering=0) as m:
        m.seek(base + L20)
        filep = struct.unpack('<Q', m.read(8))[0]
    return base, heap, filep

print('round,base,heap,filep,hi_dw_eq,b2,b3,f_b2,f_b3,delta_fp_base')
for i in range(ROUNDS):
    start()
    pid = find_pid()
    if pid is None:
        print(f'{i},START_FAIL', flush=True)
        continue
    time.sleep(2.0)  # let logging init (FILE* allocated)
    try:
        s = sample(pid)
    except Exception as e:
        s = None
    if s:
        base, heap, filep = s
        eq = (base >> 32) == (filep >> 32)
        print(f'{i},0x{base:x},{heap and hex(heap)},0x{filep:x},{eq},'
              f'{(base>>16)&0xff:02x},{(base>>24)&0xff:02x},'
              f'{(filep>>16)&0xff:02x},{(filep>>24)&0xff:02x},'
              f'0x{filep-base:x}', flush=True)
    else:
        print(f'{i},SAMPLE_FAIL', flush=True)
    try:
        os.kill(pid, 9)
    except Exception:
        pass
    time.sleep(1.0)
print('done', flush=True)

