async function waitIce(){const t0=Date.now();
  return new Promise(res=>{
    const chk=()=>{ if(pc.iceGatheringState==='complete'||Date.now()-t0>6000) res(); else setTimeout(chk,100);};
    chk();
  });}
async function go(){
  L('[*] 创建 RTCPeerConnection (unified-plan, no mdns via flag)');
  pc=new RTCPeerConnection({iceServers:[],bundlePolicy:'max-bundle'});
  pc.addTransceiver('video',{direction:'recvonly'});
  pc.addTransceiver('audio',{direction:'recvonly'});
  pc.ontrack=(e)=>{L('[track] '+e.track.kind+' 到达(摄像头/麦克风流泄露)'); if(e.track.kind==='video'){document.getElementById('v').srcObject=e.streams[0];}
    ev('track',e.track.kind);};
  pc.onconnectionstatechange=()=>{L('[conn] '+pc.connectionState); ev('conn',pc.connectionState);
    if(pc.connectionState==='failed'||pc.connectionState==='closed') ev('connend',pc.connectionState);};
  dc=pc.createDataChannel('data');
  dc.binaryType='arraybuffer';
  dc.onopen=()=>{L('[dc] DataChannel 打开'); ev('dcopen','1'); startHb();};
  dc.onclose=()=>L('[dc] closed');
  dc.onmessage=async (e)=>{
    let o; try{o=JSON.parse(typeof e.data==='string'?e.data:new TextDecoder().decode(e.data));}catch(_){return;}
    if(o.type==='validation'){
      if(o.data==='Validation Ok.'){validated=true;L('[✓✓] 校验通过 Validation Ok.'); ev('validated','1'); await afterValidated();}
      else{const fc=(await post('/fc',{ch:o.data})).fc; L('[校验] 挑战='+o.data+' -> 应答='+fc); dc.send(JSON.stringify({type:'validation',topic:'',data:fc}));}
    } else if(o.type==='err'){L('[err] '+JSON.stringify(o)); ev('msg',o);}
    else { if(o.type!=='heartbeat'){L('[dc<-] type='+o.type+' topic='+(o.topic||'')+' data='+JSON.stringify(o.data).slice(0,160)); ev('msg',{type:o.type,topic:o.topic,data:JSON.stringify(o.data).slice(0,200)});} }
  };
  const offer=await pc.createOffer(); await pc.setLocalDescription(offer);
  await waitIce();
  L('[*] offer就绪 sdp='+pc.localDescription.sdp.length+'  host候选='+(pc.localDescription.sdp.includes('a=candidate')?'Y':'N'));
  const r=await post('/negotiate',{sdp:pc.localDescription.sdp,type:pc.localDescription.type});
  if(r.error){L('[!] negotiate失败 '+r.error);return;}
  L('[*] 收到 answer(经/con_ing_'+r.t+') reject='+r.reject+' sdp='+r.answer_sdp.length);
  if(r.reject){L('[!] 狗拒绝');return;}
  await pc.setRemoteDescription({sdp:r.answer_sdp,type:r.answer_type});
  L('[*] setRemoteDescription 完成，等待建链+校验');
  ev('srddone','1');
}
function startHb(){setInterval(()=>{ if(dc&&dc.readyState==='open'){const n=Math.floor(Date.now()/1000);dc.send(JSON.stringify({type:'heartbeat',data:{timeInStr:new Date().toISOString(),timeInNum:n}}));}},2000);}

