2	<body><pre id="log" style="font-size:11px"></pre>
3	<script>
4	const L=m=>{document.getElementById('log').textContent+=m+'
5	';};
6	const ev=(k,d)=>fetch('/event',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:k,data:d})}).catch(()=>{});
7	async function post(p,o){return (await fetch(p,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})).json();}
8	const wI=()=>new Promise(r=>{const t=Date.now();(function c(){if(pc.iceGatheringState==='complete'||Date.now()-t>6000)r();else setTimeout(c,100);})();});
9	function b64(buf){let s='';const b=new Uint8Array(buf);for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode.apply(null,b.subarray(i,i+8192));return btoa(s);}
10	let pc,dc,bn=0;
11	async function go(){
12	pc=new RTCPeerConnection({iceServers:[],bundlePolicy:'max-bundle'});
13	pc.addTransceiver('video',{direction:'recvonly'});pc.addTransceiver('audio',{direction:'recvonly'});
14	pc.ontrack=e=>L('[track]'+e.track.kind);
15	pc.onconnectionstatechange=()=>{L('[conn]'+pc.connectionState);ev('conn',pc.connectionState);};
16	dc=pc.createDataChannel('data');dc.binaryType='arraybuffer';
17	dc.onopen=()=>L('[dc]open');
18	dc.onmessage=async e=>{
19	if(e.data instanceof ArrayBuffer){
20	bn++;const u=new Uint8Array(e.data);
21	const hl=new Uint16Array(e.data,0,1)[0];
22	if(hl>0&&hl<u.length-4){
23	const hj=new TextDecoder().decode(u.slice(4,4+hl));
24	const img=u.slice(4+hl);
25	let f='bin';if(img[0]==255&&img[1]==216)f='jpg';else if(img[0]==137&&img[1]==80)f='png';
26	L('[F'+bn+']'+img.length+'B '+f+' ['+img.slice(0,6).join(',')+'] '+hj.slice(0,90));
27	if(bn<=8){fetch('/save_frame',{method:'POST',headers:{'Content-Type':'text/plain'},body:'f'+bn+'_'+f+':'+b64(img)}).catch(()=>{});ev('photo',{n:bn,fmt:f,sz:img.length});}
28	if(bn===1&&f==='jpg')window.photoB64=b64(img);
29	if(bn===2)window.frame2B64=b64(img);
30	}else{L('[F'+bn+'] raw '+u.length+'B');}
31	return;}
32	let o;try{o=JSON.parse(e.data);}catch(_){return;}
33	if(o.type==='validation'){
34	if(o.data==='Validation Ok.'){L('[OK]');ev('validated','1');
35	// 1.videohub 1001(RGB+帧2)
36	sr('rt/api/videohub/request',1001);await s(3);
37	// 2.back_videohub 1001(可能热成像)
38	sr('rt/api/back_videohub/request',1001);await s(3);
39	// 3.GET_CONFIG(查硬件)
40	sr('rt/api/config/request',1002);await s(2);
41	// 4.videohub 1002-1004
42	sr('rt/api/videohub/request',1002);await s(2);
43	sr('rt/api/videohub/request',1003);await s(2);
44	sr('rt/api/videohub/request',1004);
45	}else{const fc=(await post('/fc',{ch:o.data})).fc;dc.send(JSON.stringify({type:'validation',topic:'',data:fc}));}
46	}else if(o.type==='res'){
47	let d='';try{d=JSON.stringify(o.data).slice(0,150);}catch(_){d=String(o.data).slice(0,150);}
48	L('[res]'+d);ev('msg',{type:'res',data:d});
49	}else if(o.type!=='heartbeat'&&o.type!=='errors'&&o.type!=='err'){L('[<-]'+o.type);}
50	};
51	function sr(t,a){dc.send(JSON.stringify({type:'req',topic:t,data:{header:{identity:{id:Math.floor(Math.random()*1e9),api_id:a}},parameter:'{}'}}));L('[CMD]'+t.split('/').slice(-2).join('/')+' '+a);}
52	function s(ms){return new Promise(r=>setTimeout(r,ms*1000));}
53	const of=await pc.createOffer();await pc.setLocalDescription(of);await wI();
54	const r=await post('/negotiate',{sdp:pc.localDescription.sdp,type:pc.localDescription.type});
55	if(r.error){L('[!]'+r.error);return;}
56	await pc.setRemoteDescription({sdp:r.answer_sdp,type:r.answer_type});L('[*]done');
57	setInterval(()=>{if(dc&&dc.readyState==='open')dc.send(JSON.stringify({type:'heartbeat',data:{timeInNum:Math.floor(Date.now()/1000)}}));},2000);
58	}
59	go();
60	</script></body></html>

