#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""C2 probe v4: decode framed binary messages, single valid request."""
import time, json, sys, requests
from playwright.sync_api import sync_playwright

sys.stdout.reconfigure(encoding='utf-8', errors='replace')
CHROME = r"C:\Program Files\Google\Chrome\Application\chrome.exe"
BR = "http://127.0.0.1:9999/"

def main():
    with sync_playwright() as p:
        browser = p.chromium.launch(executable_path=CHROME, headless=True, args=[
            "--disable-features=WebRtcHideLocalIpsWithMdns", "--no-sandbox"])
        page = browser.new_context().new_page()
        page.goto(BR, wait_until="domcontentloaded")
        t0 = time.time(); s = {}
        while time.time() - t0 < 40:
            s = requests.get(BR + "status", timeout=3).json()
            if s.get("validated"):
                break
            time.sleep(1)
        if not s.get("validated"):
            print("[!] never validated"); browser.close(); return
        print("[+] validated", flush=True)
        page.evaluate("""() => {
          window.binlog = [];
          dc.addEventListener('message', e => {
            try {
              if (typeof e.data === 'string') {
                if (!e.data.includes('heartbeat') && !e.data.includes('lowstate'))
                  window.binlog.push('[str] ' + e.data.slice(0, 300));
                return;
              }
              const u = new Uint8Array(e.data);
              const hl = new Uint16Array(e.data.buffer, 0, 1)[0];
              let hdr = '';
              if (hl > 0 && hl < u.length - 4)
                hdr = new TextDecoder().decode(u.slice(4, 4 + Math.min(hl, 400)));
              window.binlog.push('[bin ' + u.length + 'B hl=' + hl + '] ' + hdr);
            } catch(err) { window.binlog.push('[err ' + err + ']'); }
          });
        }""")
        # baseline: capture 4s of background traffic
        time.sleep(4)
        bg = page.evaluate("() => window.binlog.splice(0)")
        print(f"--- background {len(bg)} msg:")
        for x in bg[:6]: print("   ", x[:260])
        # send the valid request
        msg = {"type": "rtc_inner_req", "req_type": "request_static_file",
               "related_bussiness": "uslam_final_pcd", "req_uuid": "v4-a"}
        page.evaluate("(m) => dc.send(JSON.stringify(m))", msg)
        print("--- sent request_static_file(uslam_final_pcd), waiting 8s...")
        time.sleep(8)
        rx = page.evaluate("() => window.binlog.splice(0)")
        print(f"--- after request {len(rx)} msg:")
        for x in rx[:12]: print("   ", x[:300])
        browser.close()

main()

